// Work out where this lead actually came from.
// First match wins. Anything unmatched is marked Unknown, never guessed —
// a wrong source is worse than an honest gap.

const b = $json.body ?? $json;
const q = b.query ?? {};
const get = (...keys) => {
  for (const k of keys) {
    const v = b[k] ?? q[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const gclid    = get('gclid');
const fbclid   = get('fbclid');
const utmSrc   = get('utm_source').toLowerCase();
const utmMed   = get('utm_medium').toLowerCase();
const referrer = get('referrer', 'document_referrer', 'http_referer');
const tracked  = get('tracked_number', 'called_number', 'to');

let source = 'Unknown';
let clickId = '';

if (tracked) {
  source = 'Phone';                                  // a tracked number identifies the source outright
} else if (gclid)  { source = 'Google Ads';   clickId = gclid; }
else if (fbclid)   { source = 'Facebook Ads'; clickId = fbclid; }
else if (utmSrc) {
  const key = utmSrc.replace(/[^a-z]/g, '');
  const paid = utmMed.includes('cpc') || utmMed.includes('paid') || utmMed.includes('ppc');
  const map = {
    google: paid ? 'Google Ads' : 'Website form',
    adwords: 'Google Ads', googleads: 'Google Ads',
    facebook: 'Facebook Ads', fb: 'Facebook Ads', meta: 'Facebook Ads', instagram: 'Facebook Ads',
    angi: 'Angi', angieslist: 'Angi', homeadvisor: 'Angi',
    thumbtack: 'Thumbtack',
    lsa: 'Google LSA', localservices: 'Google LSA',
    referral: 'Referral',
  };
  source = map[key] || 'Unknown';
} else if (referrer) {
  const r = referrer.toLowerCase();
  if (r.includes('angi') || r.includes('homeadvisor')) source = 'Angi';
  else if (r.includes('thumbtack')) source = 'Thumbtack';
  else if (r.includes('localservices') || r.includes('/lsa')) source = 'Google LSA';
  else if (r.includes('facebook') || r.includes('instagram')) source = 'Facebook Ads';
  else if (r.includes('yourdomain.com')) source = 'Website form';
  else source = 'Referral';
} else if (get('name', 'email', 'phone')) {
  source = 'Website form';                           // landed direct, filled the form in
}

const digits = (s) => s.replace(/[^\d+]/g, '');
const service = get('service');
const known = ['Moving', 'Roofing', 'Plumbing', 'HVAC', 'Solar'];
const matchedService = known.find(s => s.toLowerCase() === service.toLowerCase());

// Columns must sit at the top level for the Airtable step to map them.
const row = {
  'Name':           get('name', 'full_name', 'first_name') || 'Unnamed lead',
  'Received':       new Date().toISOString(),
  'Phone':          digits(get('phone', 'phone_number', 'from')),
  'Email':          get('email'),
  'Service':        matchedService || (service ? 'Other' : ''),
  'Source':         source,
  'Campaign':       get('utm_campaign'),
  'Landing page':   get('landing_page', 'page_url', 'url'),
  'Tracked number': digits(tracked),
  'Click ID':       clickId,
  'Stage':          'New',
  'Message':        get('message', 'notes', 'comments'),
};

// Drop empties rather than writing blanks into Airtable.
for (const k of Object.keys(row)) if (row[k] === '' || row[k] == null) delete row[k];

return [{ json: row }];

// The lookup replaced our lead with the Sources row, so pull the lead back
// and copy the rate across. Missing rate is fine — the field stays empty and
// the summary will report how many leads it could not price.

const lead = { ...$('Work out the source').first().json };
const rate = $json['Cost per lead'] ?? $json.fields?.['Cost per lead'];

if (rate !== undefined && rate !== null && rate !== '') {
  lead['Lead cost'] = Number(rate);
}

return [{ json: lead }];

// Decide whether this lead is worth messaging, then write the reply.
//
// Validation, not verification. We check the data ourselves in milliseconds
// rather than asking the person to prove anything — making them confirm an
// email before we reply would destroy the sub-minute response we are selling.

const raw   = $('Lead arrives').first().json.body ?? $('Lead arrives').first().json;
const lead  = $('Attach the cost').first().json;
const saved = $('Save to Airtable').first().json;
const dupes = $('Look for recent duplicates').all().map(i => i.json);

const now = new Date();
const received = new Date(lead['Received']);
const seconds = Math.max(1, Math.round((now - received) / 1000));

const email = String(lead['Email'] || '').trim();
const phone = String(lead['Phone'] || '').replace(/[^\d]/g, '');

const reasons = [];

// 1. Honeypot — a field hidden from people, visible to bots. Anything in it is automated.
if (String(raw.website || raw.company_url || raw._hp || '').trim()) reasons.push('honeypot filled');

// 2. Filled in too fast to have been typed.
// Measure against when the lead ARRIVED, not now — by the time this runs we
// have already spent a few seconds saving and checking for duplicates, which
// would make every submission look slow.
const loadedAt = Number(raw.form_loaded_at || 0);
if (loadedAt > 0) {
  const took = (received.getTime() - loadedAt) / 1000;
  if (took < 2) reasons.push(`submitted in ${took.toFixed(1)}s`);
}

// 3. Do we have any way to reach them at all.
const emailOk = /^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/.test(email);
if (!emailOk && !phone) reasons.push('no usable contact details');

// 4. Throwaway inboxes.
const throwaway = ['mailinator.com','guerrillamail.com','10minutemail.com','tempmail.com',
                   'yopmail.com','trashmail.com','sharklasers.com','getnada.com'];
const domain = email.split('@')[1]?.toLowerCase() || '';
if (domain && throwaway.includes(domain)) reasons.push('disposable email');

// 5. Already contacted this person in the last half hour — do not message twice.
const recentDupe = dupes.some(d => {
  if (!d.id || d.id === saved.id) return false;
  const t = new Date(d['Received'] || 0);
  return (now - t) < 30 * 60 * 1000;
});
if (recentDupe) reasons.push('duplicate within 30 minutes');

// --- compose the reply ---
const rawName = String(lead['Name'] || '').trim();
const usable = rawName && !/^unnamed/i.test(rawName);
const firstName = usable ? rawName.split(/\s+/)[0] : 'there';
const service = String(lead['Service'] || '').toLowerCase();
const job = service && service !== 'other' ? `your ${service} job` : 'your job';

const text =
  `Hi ${firstName} — thanks for getting in touch about ${job}. ` +
  `I've got your details and someone will call you shortly. ` +
  `What's the best time to reach you today?`;

const send = reasons.length === 0 && emailOk;

return [{
  json: {
    id: saved.id,
    'First contact': now.toISOString(),
    // Seconds is the real figure. Minutes is kept for continuity, but a
    // sub-minute reply rounds to 0 there — never show it on its own.
    'Response seconds': seconds,
    'Response minutes': Math.round(seconds / 60),
    'First reply text': text,
    'Reply channel': send ? 'Email'
      : (reasons.length ? `Not sent — ${reasons[0]}` : 'Not sent — no contact details'),
    'Stage': 'Contacted',
    _send: send,
    _to: email,
    _subject: `Thanks for your enquiry${usable ? ', ' + firstName : ''}`,
    _text: text,
    _seconds: seconds,
    _blocked: reasons.join('; '),
  },
}];

// Keys beginning with _ are working values, not Airtable columns. Auto-mapping
// would try to write them as fields and the update would fail, so they are
// stripped here rather than scattered through the flow.

const row = { ...$('Check the lead is real').first().json };

let emailed = false;
try { emailed = !!$('Send the email').first().json?.id; } catch (e) { emailed = false; }
if (row._send && !emailed) row['Reply channel'] = 'Not sent — send failed';

console.log(`replied in ${row._seconds}s` + (row._blocked ? ` | blocked: ${row._blocked}` : ''));

for (const k of Object.keys(row)) if (k.startsWith('_')) delete row[k];
return [{ json: row }];

